-- ---------------------------------------------------------------------------
-- Definitions, per family (spec 11.3), scraped from the 2026 Committee
-- Handbook and the committee's own description of the ground. 57 of 98;
-- the other 41 stay NULL until Rodeo Express writes them up, and the app
-- keeps saying so.
-- ---------------------------------------------------------------------------

-- Starters. The handbook: Rodeo Express took the Bus Starter positions over
-- from METRO in 2007; the red vest is the Bus Operations Starter vest and
-- carries a radio; never work in the street or stand in front of a moving
-- vehicle. The committee: starters stand in the bus lanes, even with their
-- stop.
UPDATE position SET definition = 'Dispatches buses for the Reed Road stop from the bus lanes on the west side of the tent, even with the stop - red vest and radio, a job Rodeo Express has staffed itself since taking it over from METRO in 2007. Never work in the street or stand in front of a moving bus.'
 WHERE label IN ('Reed Starter 1', 'Reed Starter 2');
UPDATE position SET definition = 'Dispatches buses for the OST/Smithlands stop from the bus lanes on the west side of the tent, even with the stop - red vest and radio, a job Rodeo Express has staffed itself since taking it over from METRO in 2007. Never work in the street or stand in front of a moving bus.'
 WHERE label IN ('OST Starter 1', 'OST Starter 2');
UPDATE position SET definition = 'Dispatches buses for the West Loop stop from the bus lanes on the west side of the tent, even with the stop - red vest and radio, a job Rodeo Express has staffed itself since taking it over from METRO in 2007. Never work in the street or stand in front of a moving bus.'
 WHERE label IN ('WL Starter 1', 'WL Starter 2');
UPDATE position SET definition = 'Dispatches buses for the Monroe stop from the bus lanes on the west side of the tent, even with the stop - red vest and radio, a job Rodeo Express has staffed itself since taking it over from METRO in 2007. Never work in the street or stand in front of a moving bus.'
 WHERE label IN ('Monroe Starter 1', 'Monroe Starter 2');
UPDATE position SET definition = 'Dispatches buses for the Maxey stop from the bus lanes on the west side of the tent, even with the stop - red vest and radio, a job Rodeo Express has staffed itself since taking it over from METRO in 2007. Never work in the street or stand in front of a moving bus.'
 WHERE label = 'Maxey Starter';
UPDATE position SET definition = 'Dispatches buses for The Woodlands Express stop from the bus lanes on the west side of the tent, even with the stop - red vest and radio. Never work in the street or stand in front of a moving bus.'
 WHERE label = 'Woodlands Starter';
UPDATE position SET definition = 'Dispatches buses for the Special Events stop from the bus lanes on the west side of the tent, even with the stop - red vest and radio. Never work in the street or stand in front of a moving bus.'
 WHERE label = 'Special Events Starter';
UPDATE position SET definition = 'Dispatches buses for the Gold Badge / LT stop - red vest and radio, a job Rodeo Express has staffed itself since taking it over from METRO in 2007. Never work in the street or stand in front of a moving bus.'
 WHERE label IN ('GB/LT Starter 1', 'GB/LT Starter 2');
UPDATE position SET definition = 'Dispatches buses through the lanes while arriving guests unload - the first phase of the night, shared by several committeemen at once. Red vest and radio, and never work in the street.'
 WHERE label = 'Unload Starter';

-- Computers and counters. The handbook: real-time passenger counts have
-- driven Rodeo Express bus operations since 1991, and counts are entered
-- into the committee computer system. The committee: computers, counters
-- and runners work just outside the west side of the tent.
UPDATE position SET definition = 'Enters the Reed Road boarding counts into the Rodeo Express computer system, working just outside the west side of the tent. Real-time passenger counts have driven bus operations since 1991.'
 WHERE label = 'Reed Computer';
UPDATE position SET definition = 'Enters boarding counts for the employee buses at the Reed Road employee gates, working just outside the west side of the tent. NRG, Aramark, Aramco and carnival employees ride with their credentials.'
 WHERE label = 'Employee Computer';
UPDATE position SET definition = 'Enters the Gold Badge / LT boarding counts into the Rodeo Express computer system. Real-time passenger counts have driven bus operations since 1991.'
 WHERE label = 'GB/LT Computer';
UPDATE position SET definition = 'Enters the OST/Smithlands boarding counts into the Rodeo Express computer system, working just outside the west side of the tent. Real-time passenger counts have driven bus operations since 1991.'
 WHERE label = 'OST Computer';
UPDATE position SET definition = 'Enters the West Loop boarding counts into the Rodeo Express computer system, working just outside the west side of the tent. Real-time passenger counts have driven bus operations since 1991.'
 WHERE label = 'WL Computer';
UPDATE position SET definition = 'Enters the Monroe boarding counts into the Rodeo Express computer system, working just outside the west side of the tent. Real-time passenger counts have driven bus operations since 1991.'
 WHERE label = 'Monroe Computer';
UPDATE position SET definition = 'Enters the Maxey boarding counts into the Rodeo Express computer system, working just outside the west side of the tent. Real-time passenger counts have driven bus operations since 1991.'
 WHERE label = 'Maxey Computer';
UPDATE position SET definition = 'Records counts as arriving buses unload - the first phase of the night, shared by more than one committeeman at once, working just outside the west side of the tent.'
 WHERE label = 'Unload Computer';

UPDATE position SET definition = 'Counts every passenger boarding at the Reed Road stop. The counts feed the computer and are the real-time ridership numbers Rodeo Express has used to refine bus operations since 1991.'
 WHERE label IN ('Reed Counter 1', 'Reed Counter 2');
UPDATE position SET definition = 'Counts passengers boarding the employee buses at the Reed Road employee gates. The counts feed the computer and the daily ridership numbers.'
 WHERE label IN ('Employee Counter 1', 'Employee Counter 2');
UPDATE position SET definition = 'Counts every passenger boarding at the Gold Badge / LT stop. The counts feed the computer and are the real-time ridership numbers Rodeo Express has used to refine bus operations since 1991.'
 WHERE label IN ('GB/LT Counter 1', 'GB/LT Counter 2');
UPDATE position SET definition = 'Counts every passenger boarding at the OST/Smithlands stop. The counts feed the computer and are the real-time ridership numbers Rodeo Express has used to refine bus operations since 1991.'
 WHERE label IN ('OST Counter 1', 'OST Counter 2');
UPDATE position SET definition = 'Counts every passenger boarding at the West Loop stop. The counts feed the computer and are the real-time ridership numbers Rodeo Express has used to refine bus operations since 1991.'
 WHERE label IN ('WL Counter 1', 'WL Counter 2');
UPDATE position SET definition = 'Counts every passenger boarding at the Monroe stop. The counts feed the computer and are the real-time ridership numbers Rodeo Express has used to refine bus operations since 1991.'
 WHERE label IN ('Monroe Counter 1', 'Monroe Counter 2');
UPDATE position SET definition = 'Counts every passenger boarding at the Maxey stop. The counts feed the computer and are the real-time ridership numbers Rodeo Express has used to refine bus operations since 1991.'
 WHERE label IN ('Maxey Counter 1', 'Maxey Counter 2');

-- The crosswalks and the bridge. The handbook: the walkover bridge went in
-- at Naomi in 2017 to handle patrons walking in from the east side and to
-- improve the movement of buses; flashlights must be used when assisting
-- pedestrians across crosswalks; never stand in front of moving vehicles.
UPDATE position SET definition = 'Directs buses and patrons from the center of the Naomi crosswalk, northwest of the tent - radio required. Use a flashlight when assisting pedestrians across, and never stand in front of moving vehicles.'
 WHERE label = 'Center Starter';
UPDATE position SET definition = 'Perimeter position on the Naomi crosswalk, northwest of the tent, guiding patrons safely across. Flashlights must be used when assisting pedestrians across a crosswalk; safety vest at all times.'
 WHERE label IN ('Naomi Crosswalk Perimeter 1', 'Naomi Crosswalk Perimeter 2',
                 'Naomi Crosswalk Perimeter 3', 'Naomi Crosswalk Perimeter 4',
                 'Naomi Crosswalk Perimeter 5', 'Naomi Crosswalk Perimeter 6');
UPDATE position SET definition = 'Works the walkover bridge at Naomi, northwest of the tent - installed in 2017 to carry patrons walking in from the east side while the buses keep moving beneath it.'
 WHERE label IN ('Naomi Bridge 1', 'Naomi Bridge 2', 'Naomi Bridge 3',
                 'Naomi Bridge 4', 'Naomi Bridge 5', 'Naomi Bridge 6');
UPDATE position SET definition = 'Directs buses and patrons from the center of the Holly Hall crosswalk, southwest of the tent - radio required. Use a flashlight when assisting pedestrians across, and never stand in front of moving vehicles.'
 WHERE label = 'Holly Hall Center';
UPDATE position SET definition = 'Works the Holly Hall crosswalk, southwest of the tent, guiding patrons safely across. Flashlights must be used when assisting pedestrians across a crosswalk; safety vest at all times.'
 WHERE label IN ('Holly Hall 1', 'Holly Hall 2', 'Holly Hall 3',
                 'Holly Hall 4', 'Holly Hall 5');

-- The committee gate. The committee: it sits on the north side of the Bus
-- Ops office complex. The handbook: everyone signs in on arrival and signs
-- out before leaving.
UPDATE position SET definition = 'Works the committee gate on the north side of the Bus Ops office complex - the gate committeemen use to reach the tarmac. Everyone signs in with team leadership on arrival and signs out before leaving.'
 WHERE label IN ('Main Committee Gate Lead', 'Main Committee Gate 2');

-- ---------------------------------------------------------------------------
-- The assign board shows definitions, so boards still live when this lands
-- need to hear about it — same rule as every Matrix Editor write (spec 10.2).
-- ---------------------------------------------------------------------------

UPDATE state_version sv
  JOIN shift sh ON sh.id = sv.shift_id
   SET sv.version = sv.version + 1
 WHERE sh.ends_at > UTC_TIMESTAMP();
